    if (!existing) throw new Error('Sub-category not found.');
    await firebaseDbRequest_('itemSubCategories/' + subCategoryId, 'patch', { Status: 'Inactive', UpdatedAt: new Date().toISOString(), UpdatedBy: user.profile.username || user.uid }, idToken);
    return { success: true };
